suppressPackageStartupMessages({library(data.table);library(msigdbr)});setDTthreads(2)
base='almanac_conditionals/state_conditioned_bridge/program_first';out=file.path(base,'results');m=fread(file.path(out,'frozen_program_weights.tsv'));P=sort(unique(m$program))
sets=rbindlist(list(Hallmark=as.data.table(msigdbr(species='Homo sapiens',category='H'))[,.(term=gs_name,gene=gene_symbol)],Reactome=as.data.table(msigdbr(species='Homo sapiens',category='C2',subcategory='CP:REACTOME'))[,.(term=gs_name,gene=gene_symbol)],GO_BP=as.data.table(msigdbr(species='Homo sapiens',category='C5',subcategory='GO:BP'))[,.(term=gs_name,gene=gene_symbol)]),idcol='collection');sets=unique(sets);saveRDS(sets,file.path(base,'artifacts/theme_gene_sets.rds'))
backgrounds=list(all_eligible=sort(unique(m$gene)))
res=list();for(bg in names(backgrounds)){u=backgrounds[[bg]];s=sets[gene%in%u];terms=s[,.(set_size=uniqueN(gene),members=list(unique(gene))),by=.(collection,term)][set_size>=3];for(prog in P){g=m[program==prog,gene];d=copy(terms);d[,overlap_genes:=vapply(members,function(x)paste(sort(intersect(x,g)),collapse=','),character(1))];d[,overlap:=vapply(members,function(x)length(intersect(x,g)),integer(1))];d[,`:=`(program=prog,program_size=length(g),background=bg,background_size=length(u))];d[,p:=phyper(overlap-1,set_size,background_size-set_size,program_size,lower.tail=FALSE)];d[,q:=p.adjust(p,'BH'),by=collection];d[,fold_enrichment:=(overlap/program_size)/(set_size/background_size)];d[,members:=NULL];res[[paste(bg,prog)]]=d}}
r=rbindlist(res);fwrite(r,file.path(out,'program_theme_enrichment.tsv.gz'),sep='\t');top=r[overlap>=2][order(q,p,-overlap)][,head(.SD,5),by=.(background,program)];fwrite(top,file.path(out,'program_theme_top_terms.tsv'),sep='\t');print(top[background=='all_eligible',.(program,collection,term,overlap,q,overlap_genes)]);cat('\nSignificant counts\n');print(r[q<.05,.(terms=.N),by=.(background,program,collection)])
